import{_ as r,o as t,c as n,O as a}from"./chunks/framework.2c2d5a61.js";const p="/cao_note/java-10w/image477.jpeg",i="/cao_note/java-10w/image485.jpeg",s="/cao_note/java-10w/image487.jpeg",e="/cao_note/java-10w/image491.jpeg",l="/cao_note/java-10w/image492.jpeg",g="/cao_note/java-10w/image493.jpeg",d="/cao_note/java-10w/image494.jpeg",h="/cao_note/java-10w/image520.jpeg",c="/cao_note/java-10w/image521.jpeg",u="/cao_note/java-10w/image522.jpeg",b="/cao_note/java-10w/image523.jpeg",_="/cao_note/java-10w/image243.png",m="/cao_note/java-10w/image245.png",y=JSON.parse('{"title":"分布式与高并发","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/12-分布式与高并发.md","filePath":"interview/后端/Java/12-分布式与高并发.md","lastUpdated":1793001193000}'),k={name:"interview/后端/Java/12-分布式与高并发.md"};function P(q,o,C,x,f,D){return t(),n("div",null,o[0]||(o[0]=[a('<h1 id="分布式与高并发" tabindex="-1">分布式与高并发 <a class="header-anchor" href="#分布式与高并发" aria-label="Permalink to &quot;分布式与高并发&quot;">​</a></h1><blockquote><p><strong>怎么用这份笔记</strong></p><ul><li>分级：<code>★★★ 必须吃透</code> / <code>★★☆ 了解即可（记结论就行）</code> / <code>★☆☆ 可以跳过（一句话看一眼）</code></li><li>【简历亮点，高频追问】：简历里写过的技术，面试官会顺着往下挖，这段必须能展开讲</li><li>每个考点按「定义 → 原理 → 要点 / 易错点」组织，只讲知识点</li></ul></blockquote><hr><h2 id="_1-cap-与-base-★★★" tabindex="-1">1. CAP 与 BASE ★★★ <a class="header-anchor" href="#_1-cap-与-base-★★★" aria-label="Permalink to &quot;1. CAP 与 BASE ★★★&quot;">​</a></h2><p><strong>CAP</strong> 指一致性（Consistency）、可用性（Availability）、分区容错（Partition tolerance）。分布式系统里网络分区不可避免，<strong>P 必须保</strong>，所以实际只能在 <strong>C 和 A</strong> 之间取舍，三者无法同时满足。</p><ul><li><strong>CP</strong>：优先一致性和分区容错，典型是 <strong>ZooKeeper、etcd</strong>。</li><li><strong>AP</strong>：优先可用性和分区容错，典型是 <strong>Eureka</strong>。</li></ul><p><strong>BASE</strong> 是对 CAP 的妥协，包含三个要素：</p><ul><li><strong>基本可用</strong>：允许损失部分可用性，例如响应变慢、降级；</li><li><strong>软状态</strong>：允许中间状态存在，不要求各副本时刻相同；</li><li><strong>最终一致</strong>：不追求实时强一致，接受「过一会儿才一致」。</li></ul><p>落地时按链路取舍：扣费、订单状态这类<strong>核心链路</strong>要强一致；跨系统上报、统计报表这类<strong>非核心链路</strong>用<strong>消息 + 重试</strong>做到最终一致即可，可用性更好。</p><hr><h2 id="_2-分布式事务方案-★★★" tabindex="-1">2. 分布式事务方案 ★★★ <a class="header-anchor" href="#_2-分布式事务方案-★★★" aria-label="Permalink to &quot;2. 分布式事务方案 ★★★&quot;">​</a></h2><p>跨服务、跨库的写操作无法靠<strong>本地事务</strong>保证，必须用分布式事务方案。</p><ul><li><strong>2PC（两阶段提交）</strong>：协调者先询问所有参与者能否提交，再统一提交或回滚。强一致，但<strong>同步阻塞</strong>、协调者<strong>单点</strong>、性能差。</li><li><strong>TCC（Try-Confirm-Cancel）</strong>：Try 预留资源，Confirm 确认提交，Cancel 取消并释放预留资源。不锁整个资源、性能较好，但<strong>侵入业务</strong>，三个方法都要按业务实现，且 Confirm / Cancel 必须<strong>幂等</strong>。</li><li><strong>SAGA</strong>：把一个长事务拆成多个本地事务，失败时按反向顺序执行<strong>补偿</strong>，达到最终一致。</li><li><strong>本地消息表</strong>：业务数据和消息记录放在同一个本地事务里落库，再由定时任务把未发送/失败的消息重投，消费端幂等收敛。</li><li><strong>事务消息</strong>：RocketMQ 的<strong>半消息</strong>机制——先发半消息，执行本地事务，再确认或回滚，保证「本地事务成功」与「消息可投递」同时成立；确认失败由 broker 回查生产者。</li><li><strong>最大努力通知</strong>：反复重试通知对方，配合<strong>定时对账</strong>兜底。</li><li>中间件是 <strong>Seata</strong>（AT / TCC / SAGA 等模式）。</li></ul><p>选型上，业务量大、链路长时优先「<strong>本地事务 + 消息 + 对账补偿</strong>」的最终一致路线：2PC 阻塞且单点，TCC 改造成本高，在高并发场景划不来；对账本身已有，用消息重试加定时对账兜底最稳。</p><hr><h2 id="_3-分布式-id-生成-★★★" tabindex="-1">3. 分布式 ID 生成 ★★★ <a class="header-anchor" href="#_3-分布式-id-生成-★★★" aria-label="Permalink to &quot;3. 分布式 ID 生成 ★★★&quot;">​</a></h2><p>分布式 ID 的要求：全局唯一、趋势递增、高可用、最好带时间信息。常见方案：</p><ul><li><strong>UUID</strong>：结合网卡、时间、随机数生成，本地生成、简单、无高可用风险；但长度长、存储冗余、<strong>无序</strong>，做数据库主键会频繁<strong>页分裂</strong>，查询效率低。</li><li><strong>数据库自增 ID</strong>：绝对有序，可用两台库设置不同步长实现高可用；但要独立部署实例、成本高，有<strong>单点</strong>和性能瓶颈。</li><li><strong>号段模式</strong>：一次从数据库批量取一段 ID 缓存在本地，减少访问数据库的次数；属于本地生成策略，存在单点故障，服务重启会造成 ID 不连续。</li><li><strong>Redis 自增</strong>：<code>incr</code> / <code>incrby</code> 原子且天然有序，性能优于数据库，对分页排序友好；代价是引入新组件、需要编码配置，单点有瓶颈时可多节点设置不同起始值和步长。</li><li><strong>雪花算法（主流）</strong>：1 位符号位 + 41 位时间戳 + 10 位机器 id + 12 位序列号，共 64 位 Long。本地生成、<strong>趋势递增</strong>、高性能，一般不会碰撞。</li></ul><p>雪花算法唯一的硬伤是<strong>依赖机器时钟</strong>：发生<strong>时钟回拨</strong>会生成重复 ID，处理方式是检测到回拨后等待时钟追上，或更换机器 id。订单号、流水号用雪花或号段都合适，趋势递增对 <strong>B+ 树</strong>索引也友好。</p><hr><p><strong>补充（原文详解）</strong></p><p>分布式ID的特性</p><p>唯一性：确保生成的ID是全网唯一的。</p><p>有序递增性：确保生成的ID是对于某个用户或者业务是按一定的数字有序递增的。</p><p>高可用性：确保任何时候都能正确的生成ID。</p><p>带时间：ID里面包含时间，一眼扫过去就知道哪天的交易。</p><p>分布式ID生成方案</p><ol><li>UUID</li></ol><p>算法的核心思想是结合机器的网卡、当地时间、 一个随记数来生成UUID。</p><p>. 优点：本地生成，生成简单，性能好，没有高可用风险</p><p>缺点：长度过长，存储冗余，且无序不可读，查询效率低</p><ol start="2"><li>数据库自增ID</li></ol><p>使用数据库的id自增策略，如 MySQL 的 auto_increment。并且可以使用两台数据库分别设置不同步长，生成不重复ID的策略来实现高可用。</p><p>优点：数据库生成的ID绝对有序，高可用实现方式简单</p><p>缺点：需要独立部署数据库实例，成本高，有性能瓶颈</p><ol start="3"><li>批量生成ID</li></ol><p>一次按需批量生成多个ID，每次生成都需要访问数据库，将数据库修改为最大的ID值，并在内存中记录当前值及最大值。</p><p>优点：避免了每次生成ID都要访问数据库并带来压力，提高性能</p><p>缺点：属于本地生成策略，存在单点故障，服务重启造成ID不连续</p><ol start="4"><li>Redis生成ID</li></ol><p>Redis的所有命令操作都是单线程的，本身提供像 incr 和 increby 这样的自增原子命令，所以能保证生成的 ID 肯定是唯一有序的。</p><p>优点：不依赖于数据库，灵活方便，且性能优于数据库；数字ID天然排序，对分页或者需要排序的结果很有帮助。</p><p>缺点：如果系统中没有Redis，还需要引入新的组件，增加系统复杂度；需要编码和配置的工作量比较大。</p><p>考虑到单节点的性能瓶颈，可以使用 Redis 集群来获取更高的吞吐量。假如一个集群中有5台 Redis。可以初始化每台 Redis 的值分别是1, 2, 3, 4, 5，然后步长都是 5。</p><ol start="5"><li>Twitter的snowﬂake算法（重点）</li></ol><p>Twitter 利用 zookeeper 实现了一个全局ID生成的服务 Snowﬂake</p><p>如上图的所示，Twitter 的 Snowﬂake 算法由下面几部分组成：</p><p>1位符号位：</p><p>由于 long 类型在 java 中带符号的，最高位为符号位，正数为 0，负数为 1，且实际系统中所使用的ID一般都是正数，所以最高位为 0。</p><p>41位时间戳（毫秒级）：</p><p>需要注意的是此处的 41 位时间戳并非存储当前时间的时间戳，而是存储时间戳的差值（当前时间戳 - 起始时间戳），这里的起始时间戳一般是ID生成器开始使用的时间戳，由程序来指定，所以41 位毫秒时间戳最多可以使用 (1 &lt;&lt; 41) / (1000x60x60x24x365) = 69年。</p><p>10位数据机器位：</p><p>包括5位数据标识位和5位机器标识位，这10位决定了分布式系统中最多可以部署 1 &lt;&lt; 10 = 1024</p><p>s个节点。超过这个数量，生成的ID就有可能会冲突。</p><p>12位毫秒内的序列：</p><p>这 12 位计数支持每个节点每毫秒（同一台机器，同一时刻）最多生成 1 &lt;&lt; 12 = 4096个ID</p><p>加起来刚好64位，为一个Long型。</p><p>优点：高性能，低延迟，按时间有序，一般不会造成ID碰撞</p><p>缺点：需要独立的开发和部署，依赖于机器的时钟</p><ol start="6"><li>百度UidGenerator</li></ol><p>UidGenerator是百度开源的分布式ID生成器，基于于snowﬂake算法的实现，看起来感觉还行。不过，国内开源的项目维护性真是担忧。</p><ol start="7"><li>美团Leaf</li></ol><p>Leaf 是美团开源的分布式ID生成器，能保证全局唯一性、趋势递增、单调递增、信息安全，里面也提到了几种分布式方案的对比，但也需要依赖关系数据库、 Zookeeper等中间件。</p><h2 id="_4-限流算法-令牌桶、漏桶、滑动窗口-★★★" tabindex="-1">4. 限流算法：令牌桶、漏桶、滑动窗口 ★★★ <a class="header-anchor" href="#_4-限流算法-令牌桶、漏桶、滑动窗口-★★★" aria-label="Permalink to &quot;4. 限流算法：令牌桶、漏桶、滑动窗口 ★★★&quot;">​</a></h2><p>四种常见算法：</p><ul><li><strong>固定窗口（计数器）</strong>：按周期累加访问次数，达到限流值就触发限流，下一周期清零重新计数。实现最简单，Redis 的 <code>incr</code> 原子自增即可；但存在<strong>临界突发问题</strong>——在窗口交界处两侧各打满限额，短时间内的实际流量可达限额的两倍。</li><li><strong>滑动窗口</strong>：把大周期拆成 N 个小周期，分别记录访问次数，并随时间滑动删除过期的小周期。格子划分越细，滚动越平滑、统计越精确，能解决固定窗口的临界问题。</li><li><strong>漏桶</strong>：请求先放入漏桶，容量到上限（限流值）就丢弃；漏桶以<strong>固定速率</strong>释放请求。流量严格平滑，但<strong>扛不住突发</strong>，多余请求直接被限掉。</li><li><strong>令牌桶</strong>：以固定速率（时间周期 / 限流值）往桶里放令牌，直到桶满；请求拿到令牌才通过，否则触发限流。平均速率受限，但桶里攒下的令牌<strong>允许一定突发</strong>，所以最常用。</li></ul><p>常用工具：<strong>Sentinel</strong>、Guava <strong>RateLimiter</strong>、<strong>Redis + Lua</strong>（分布式限流）、<strong>网关</strong>层限流。除了限 QPS，也可以用<strong>信号量</strong>限制对下游依赖的并发数，避免把对方打挂。</p><hr><h2 id="_5-熔断、降级、隔离-★★★" tabindex="-1">5. 熔断、降级、隔离 ★★★ <a class="header-anchor" href="#_5-熔断、降级、隔离-★★★" aria-label="Permalink to &quot;5. 熔断、降级、隔离 ★★★&quot;">​</a></h2><ul><li><strong>熔断</strong>：被动应对。依赖服务的<strong>错误率或慢调用比例超过阈值</strong>时，直接<strong>快速失败</strong>、走兜底，避免线程被拖住引发<strong>级联雪崩</strong>。状态机三态：<strong>关闭 → 打开 → 半开</strong>；打开后放少量请求到半开状态探测，恢复正常再闭合。</li><li><strong>降级</strong>：主动关功能。压力大或依赖不可用时关掉非核心功能，把资源让给<strong>核心链路</strong>，返回兜底数据（缓存旧值、默认值、空结果）。</li><li><strong>隔离</strong>：用<strong>线程池 / 信号量</strong>把不同依赖的调用隔开，一个依赖占满资源也不会拖垮整体；线程池隔离还能给每个依赖配独立超时和队列。</li></ul><p>三者通常一起用：调外部接口时配<strong>超时 + 熔断 + 降级</strong>，对方超时或报错就返回兜底数据，不影响主流程；不同外部调用分配独立线程池，互不干扰。</p><hr><h2 id="_6-接口幂等性-★★★-【简历亮点-高频追问】" tabindex="-1">6. 接口幂等性 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_6-接口幂等性-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;6. 接口幂等性 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>幂等</strong>指同一个请求执行一次和执行多次，产生的<strong>副作用相同</strong>、最终结果一致。查询天然幂等；删除第一次成功后后续返回 0，也算幂等。</p><p>需要幂等的原因：<strong>网络超时重试</strong>、用户重复点击、网关/反向代理重发、<strong>消息重复投递</strong>、Dubbo 等 RPC 框架的重试机制。</p><p>常见方案：</p><ul><li><strong>唯一索引 / 去重表</strong>：数据库层兜底，重复插入触发唯一键冲突，捕获异常后再查询已有记录返回即可。</li><li><strong>Token 机制</strong>：提交前先申请 token 存到 Redis 或 JVM 内存并设有效期，提交时<strong>校验并删除</strong> token，删除成功才算通过，然后下发新 token。必须用删除操作的返回值判断，<code>select + delete</code> 两步存在并发问题。</li><li><strong>状态机</strong>：单据状态只能按规定流转，例如只有「待支付」能改成「已支付」，重复回调因状态不满足而被拒绝。</li><li><strong>乐观锁</strong>：表增加 <code>version</code> 字段，执行 <code>update ... set version = version + 1 where version = 原值</code>，版本不符则更新失败，据此判断是否已被处理。</li><li><strong>悲观锁</strong>：<code>select ... for update</code> 锁住对应记录，需配合事务使用；锁定时间长，读多写少时慎用，且要保证命中主键或索引，否则可能锁全表。</li><li><strong>分布式锁</strong>：以订单号为 key 加锁并设置有效期（防止支付失败后锁不释放），业务执行完释放。</li><li><strong>先查后改</strong>：先查关键数据判断是否执行过，再处理；只适合并发不高的后台任务，核心高并发链路不要用。</li><li><strong>全局唯一 ID</strong>：按业务内容生成全局 ID，执行前判断该 ID 是否存在，存在即视为已执行。</li></ul><p>工程上通常<strong>多层兜底</strong>：唯一约束防脏数据、状态机管流转、分布式锁串行化并发。支付回调、上报回调这类场景重复投递是常态，应在设计阶段就按幂等实现。</p><hr><h2 id="_7-一致性哈希-★★★" tabindex="-1">7. 一致性哈希 ★★★ <a class="header-anchor" href="#_7-一致性哈希-★★★" aria-label="Permalink to &quot;7. 一致性哈希 ★★★&quot;">​</a></h2><p>普通<strong>取模哈希</strong>（<code>hash(key) % N</code>）的问题是：节点数 N 一变，几乎所有 key 的归属都要重新计算，缓存大面积失效。</p><p><strong>一致性哈希</strong>把哈希值空间组织成一个<strong>环</strong>，节点和 key 都映射到环上；key 沿环<strong>顺时针</strong>找到的第一个节点就是它的归属。节点增删时，只有该节点相邻区间内的 key 需要迁移，其余不受影响。</p><p>节点少时容易分布不均、出现<strong>数据倾斜</strong>：引入<strong>虚拟节点</strong>，每个真实节点在环上映射成多个虚拟节点，把区间打散，负载更均匀。</p><p>实际使用中一致性哈希多由客户端或中间件封装，核心价值是<strong>节点变动时只迁移少量数据</strong>，减少缓存穿透到数据库的冲击。</p><hr><h2 id="_8-秒杀系统设计-★★★-场景题" tabindex="-1">8. 秒杀系统设计 ★★★（场景题） <a class="header-anchor" href="#_8-秒杀系统设计-★★★-场景题" aria-label="Permalink to &quot;8. 秒杀系统设计 ★★★（场景题）&quot;">​</a></h2><p>核心思路是「<strong>把流量挡在数据库之前</strong>」，逐层削减：</p><ol><li><strong>前端 / CDN</strong>：页面静态化走 CDN，前端做按钮置灰、限流、答题等拦截，尽量把请求挡在源头。</li><li><strong>接入层限流</strong>：Nginx 或网关按 IP / 用户 / 接口限流，挡掉大部分无效流量。</li><li><strong>Redis 预扣库存</strong>：用 <strong>Lua</strong> 把「查库存 + 扣减」做成<strong>原子</strong>操作，<strong>防超卖</strong>；库存不足直接返回失败，不落数据库。</li><li><strong>消息队列削峰</strong>：预扣成功的请求投递到 MQ，异步生成订单，数据库按自己的消费能力处理。</li><li><strong>数据库兜底</strong>：真正扣减用<strong>乐观锁</strong> <code>where stock &gt; 0</code> 或唯一约束，保证最终不超卖。</li><li><strong>风控</strong>：一人一单，用唯一索引或 Redis 用户维度记录，防止重复抢。</li></ol><p>完整链路：点击 → CDN → 网关限流 → Redis 预扣 → MQ → 生成订单 → 落库 → 异步扣真实库存。限时优惠券这类营销活动可以复用同一套：Redis 原子预扣名额、MQ 异步落单、唯一约束防重复领。</p><hr><h2 id="_9-分布式锁的实现与问题-★★★-【简历亮点-高频追问】" tabindex="-1">9. 分布式锁的实现与问题 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_9-分布式锁的实现与问题-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;9. 分布式锁的实现与问题 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><ul><li><strong>Redis 实现</strong>：加锁用 <code>SET key value NX EX</code>，每把锁带唯一 value（如 UUID + 线程 id）。 <ul><li>释放时必须用 <strong>Lua</strong> 先校验 value 是否为自己持有、再删除，否则可能<strong>误删</strong>别人的锁（业务超时、锁已过期后被他人获取）。</li><li>业务执行时间可能超过锁过期时间，需要<strong>看门狗自动续期</strong>（Redisson 默认锁 30 秒、每 10 秒续一次）。</li><li>加锁要设<strong>等待超时</strong>，抢不到就快速失败，避免线程一直阻塞。</li><li>隐患是<strong>主从切换</strong>：主节点加锁成功后尚未同步到从节点就宕机，从节点升主后锁丢失，可用 Redlock 或业务层幂等兜底。</li></ul></li><li><strong>ZooKeeper 实现</strong>：在锁节点下创建<strong>临时顺序节点</strong>，序号最小者获得锁，其余监听前一个节点；会话断开临时节点自动删除，天然避免死锁。强一致，但性能低于 Redis。</li></ul><p>业务上主要用于把「同一资源的并发操作」<strong>串行化</strong>，例如同一订单的状态变更、同一设备的指令下发；锁的粒度按资源 id 划分，不要把不相关的操作锁在一起。</p><hr><h2 id="_10-服务治理-注册发现、配置中心、网关-★★★" tabindex="-1">10. 服务治理：注册发现、配置中心、网关 ★★★ <a class="header-anchor" href="#_10-服务治理-注册发现、配置中心、网关-★★★" aria-label="Permalink to &quot;10. 服务治理：注册发现、配置中心、网关 ★★★&quot;">​</a></h2><ul><li><strong>注册发现</strong>：服务启动后把实例信息注册到注册中心，并通过<strong>心跳续约</strong>保活；调用方拉取实例列表并本地缓存，配合<strong>负载均衡</strong>发起调用；实例下线或心跳超时会被摘除。常见组件 Eureka、Nacos、Consul。</li><li><strong>配置中心</strong>：集中管理各环境配置，支持<strong>动态刷新</strong>（推送或长轮询），改配置不用重启服务，也便于灰度与回滚。</li><li><strong>网关</strong>：统一入口，负责路由转发、鉴权、限流、灰度、协议转换和日志埋点，把横切逻辑从业务服务里收上来。</li></ul><p>需要区分两类网关：这里是 HTTP/RPC 层的<strong>服务治理网关</strong>；另一类是<strong>TCP 协议网关</strong>（如基于 Netty），负责接入设备、维护长连接和协议解析，两者职责完全不同。</p><hr><h2 id="_11-分布式链路追踪-★★☆" tabindex="-1">11. 分布式链路追踪 ★★☆ <a class="header-anchor" href="#_11-分布式链路追踪-★★☆" aria-label="Permalink to &quot;11. 分布式链路追踪 ★★☆&quot;">​</a></h2><p>目标是把一次请求跨多个服务的调用串成一条链路，用于定位瓶颈和故障。</p><ul><li><strong>traceId</strong>：一次请求全链路唯一的标识，从入口生成后一路透传，日志、RPC、消息里都带上，出问题按 traceId 就能捞出全链路日志。</li><li><strong>span</strong>：表示链路中的一次调用（服务内方法或一次远程调用），记录 spanId、parentSpanId、开始时间、耗时和标签，从而还原调用树。</li><li>透传要点：<strong>跨线程</strong>要显式传递（ThreadLocal 不会自动继承到线程池），<strong>跨服务</strong>走请求头，<strong>跨 MQ</strong> 要写进消息属性。</li><li>常见方案：<strong>SkyWalking</strong>（无侵入探针）、Zipkin、Jaeger，都遵循 OpenTracing / OpenTelemetry 规范。</li></ul><hr><h2 id="_12-缓存双写一致性与读写分离-★★☆" tabindex="-1">12. 缓存双写一致性与读写分离 ★★☆ <a class="header-anchor" href="#_12-缓存双写一致性与读写分离-★★☆" aria-label="Permalink to &quot;12. 缓存双写一致性与读写分离 ★★☆&quot;">​</a></h2><p>缓存与数据库的一致性常用 <strong>Cache Aside</strong> 模式：读时先查缓存，未命中查库并回填；写时<strong>先更新数据库，再删除缓存</strong>。</p><ul><li>不采用「更新缓存」：并发写时更新顺序可能错乱，比删缓存更容易出现<strong>不一致</strong>。</li><li>删缓存可能失败，或与并发读交错被回填旧值，可加<strong>延迟双删</strong>（更新库后删一次，延迟几百毫秒再删一次），或订阅 <strong>binlog</strong>（如 Canal）异步删缓存，把删除做成可靠的重试链路。</li><li>极端情况下仍会短暂读到旧值，强一致要求高的场景可以加分布式锁或直接读主库。</li></ul><p><strong>读写分离</strong>是主库写、从库读，用于分摊读压力；代价是<strong>主从延迟</strong>（毫秒到秒级），写完立刻要读的场景（如下单后马上查订单）应强制走主库或先读缓存。</p><hr><h2 id="_13-幂等-分布式锁-限流在订单场景的综合运用-★★☆" tabindex="-1">13. 幂等 + 分布式锁 + 限流在订单场景的综合运用 ★★☆ <a class="header-anchor" href="#_13-幂等-分布式锁-限流在订单场景的综合运用-★★☆" aria-label="Permalink to &quot;13. 幂等 + 分布式锁 + 限流在订单场景的综合运用 ★★☆&quot;">​</a></h2><p>下单链路把多个手段叠起来，逐层收口：</p><ol><li><strong>限流</strong>：入口按用户 / 接口限 QPS，防刷和防突发。</li><li><strong>幂等</strong>：用 Token 或唯一请求号防重复提交。</li><li><strong>分布式锁</strong>：按订单号或商品 id 加锁，防止并发扣减。</li><li><strong>库存扣减</strong>：用<strong>乐观锁</strong>（库存大于 0 才允许扣减）或 Redis 原子扣减，保证不超卖。</li><li><strong>生成订单</strong>：落库，订单状态用<strong>状态机</strong>约束流转。</li><li><strong>消息通知</strong>：发 MQ 通知下游，失败重试，消费端保证幂等。</li></ol><p>多层叠加后，高并发下既不会被流量打穿，也不会重复下单或超卖。</p><hr><h2 id="_14-亿级黑名单快速定位-url-布隆过滤器-★★★" tabindex="-1">14. 亿级黑名单快速定位 URL（布隆过滤器）★★★ <a class="header-anchor" href="#_14-亿级黑名单快速定位-url-布隆过滤器-★★★" aria-label="Permalink to &quot;14. 亿级黑名单快速定位 URL（布隆过滤器）★★★&quot;">​</a></h2><p><strong>布隆过滤器</strong> = 一个<strong>比特数组</strong> + k 个哈希函数。</p><ul><li>写入：对元素做 k 次哈希，把对应的 k 个 bit 位置 1。</li><li>查询：任一 bit 为 0，则元素<strong>一定不存在</strong>；全为 1，则<strong>可能存在</strong>。</li><li>因此它<strong>有误判、但不漏判</strong>，不会把存在的判成不存在。误判率由比特数组长度和哈希个数决定，通常可控在 1% 以内。</li></ul><p>特点是极省空间（亿级数据几百 MB）、查询 O(k) 极快；缺点是不支持删除（删除会牵连其他元素），需要删除时用<strong>计数布隆</strong>或定期重建。</p><p>用法是分层拦截：布隆过滤器做第一层，判断「一定不存在」的直接拒绝；命中的再回数据库精确确认，避免误判导致误杀。</p><hr><h2 id="_15-设计短网址系统-★★★-场景题" tabindex="-1">15. 设计短网址系统 ★★★（场景题） <a class="header-anchor" href="#_15-设计短网址系统-★★★-场景题" aria-label="Permalink to &quot;15. 设计短网址系统 ★★★（场景题）&quot;">​</a></h2><p>核心是「长 URL ↔ 短码」的映射与跳转。</p><ul><li><strong>短码生成</strong>有两条路： <ul><li><strong>哈希 + 截断</strong>：对长 URL 做 MD5 等哈希后取前几位，需要处理<strong>冲突</strong>（加盐重算或调整长度）。</li><li><strong>发号器</strong>：全局自增 id 转 <strong>Base62</strong>（0-9、a-z、A-Z，6 位可表示约 568 亿个），无冲突、长度短，<strong>推荐</strong>。</li></ul></li><li><strong>存储</strong>：MySQL 存映射（短码做唯一索引），Redis 缓存热点映射；也可用 K-V 存最近/最热门的对应关系，省空间又提速。</li><li><strong>跳转</strong>：用 <strong>302</strong> 临时重定向而不是 <strong>301</strong>——301 会被浏览器缓存，后续请求不再经过服务器，既统计不到点击，也无法更换目标。</li><li><strong>扩展</strong>：点击统计异步写 MQ；同一长 URL 可复用已有短码；过期短码和黑名单可结合布隆过滤器拦截。</li></ul><hr><h2 id="_16-限时订单设计-超时未支付取消-★★★-【项目强相关】" tabindex="-1">16. 限时订单设计（超时未支付取消）★★★ 【项目强相关】 <a class="header-anchor" href="#_16-限时订单设计-超时未支付取消-★★★-【项目强相关】" aria-label="Permalink to &quot;16. 限时订单设计（超时未支付取消）★★★ 【项目强相关】&quot;">​</a></h2><p>订单创建后限时（如 <strong>30 分钟</strong>）未支付则自动取消并释放资源。三种实现：</p><ul><li><strong>延迟消息（最推荐）</strong>：下单时发一条延迟消息，到点消费检查订单状态，仍未支付就取消。准时、没有扫库压力；RocketMQ 支持延迟级别，也可用 RabbitMQ 死信队列 + TTL 实现。</li><li><strong>定时任务扫描</strong>：定时扫出超时未支付订单批量取消。实现简单，但有扫描延迟和扫库压力，数据量大时要分批处理。</li><li><strong>Redis 过期监听</strong>：key 过期触发回调。精度和可靠性都差（过期事件可能丢失），生产上慎用。</li></ul><p>关键点：</p><ul><li>取消动作必须<strong>幂等</strong>，重复消息不能重复释放资源；</li><li>用<strong>状态机</strong>约束「只有待支付能改成已取消」，防止已支付订单被误取消；</li><li>取消后要<strong>回补库存 / 释放资源</strong>，回补同样要幂等；</li><li>工程上用「<strong>延迟消息 + 定时任务兜底</strong>」双保险：延迟消息保证准时，定时任务捞出漏掉的消息，避免消息丢失导致订单永久占用资源。</li></ul><hr><h2 id="_17-设计高并发支付网关-★★★-【项目强相关】" tabindex="-1">17. 设计高并发支付网关 ★★★ 【项目强相关】 <a class="header-anchor" href="#_17-设计高并发支付网关-★★★-【项目强相关】" aria-label="Permalink to &quot;17. 设计高并发支付网关 ★★★ 【项目强相关】&quot;">​</a></h2><p>关注七个方面：</p><ol><li><strong>安全</strong>：请求<strong>签名验签</strong>（私钥签名、公钥验签），<strong>防重放</strong>（时间戳 + nonce + 唯一请求号），敏感信息加密传输。</li><li><strong>高可用</strong>：多节点无状态部署，配合限流、熔断、依赖隔离，避免单点。</li><li><strong>一致性</strong>：支付结果与订单状态一致，靠状态机 + 幂等 + 对账保证。</li><li><strong>幂等</strong>：同一订单不能重复扣款，用唯一约束、状态机、分布式锁多层兜底。</li><li><strong>异步通知</strong>：回调走 MQ 异步处理，失败按退避策略重试，回调接口必须幂等。</li><li><strong>对账</strong>：T+1 与渠道对账，处理<strong>掉单</strong>（渠道成功、本地无记录）和<strong>差错账</strong>（金额或状态不一致），差错走自动补单或人工处理。</li><li><strong>状态机</strong>：支付状态严格流转（待支付 → 支付中 → 成功/失败 → 已退款），非法流转直接拒绝。</li></ol><p>回调丢失是必然而不是偶然，兜底要三层：<strong>渠道回调通知</strong>、<strong>定时主动查询</strong>（回调没来就轮询渠道查单）、<strong>T+1 对账</strong>。只靠回调一定会漏单，对账是最后一道收敛手段。</p><hr><h2 id="_18-设计打车服务-★★☆-场景题" tabindex="-1">18. 设计打车服务 ★★☆（场景题） <a class="header-anchor" href="#_18-设计打车服务-★★☆-场景题" aria-label="Permalink to &quot;18. 设计打车服务 ★★☆（场景题）&quot;">​</a></h2><p>主线是「位置存储 + 附近检索 + 派单」。</p><ul><li><strong>位置存储</strong>：司机端定时上报经纬度，用 <strong>GeoHash</strong> 把二维坐标编码成字符串，相近位置的编码前缀相同，便于按前缀检索；也可用空间索引（R 树）。</li><li><strong>附近检索</strong>：用 <strong>Redis GEO</strong>（底层是 GeoHash + 有序集合），<code>GEOADD</code> 写入、<code>GEOSEARCH</code> 按半径查附近司机并排序。</li><li><strong>派单</strong>：按距离、评分、空闲状态筛选后，用<strong>分布式锁</strong>或<strong>状态机</strong>保证一个订单只派给一个司机，防止重复派单；司机接单后状态置为「服务中」。</li><li><strong>削峰</strong>：位置上报频率高，用 WebSocket 长连接 + MQ 异步处理，只保留最新位置、旧位置覆盖，避免写放大。</li></ul><p>同类的「找附近场站」也是同一思路：经纬度 + 距离检索，只是数据量和实时性要求不同。</p><hr><h2 id="_19-设计视频流系统-★★☆" tabindex="-1">19. 设计视频流系统 ★★☆ <a class="header-anchor" href="#_19-设计视频流系统-★★☆" aria-label="Permalink to &quot;19. 设计视频流系统 ★★☆&quot;">​</a></h2><ul><li><strong>存储</strong>：视频存<strong>对象存储</strong>（S3 / OSS），支持大文件与多副本，元数据存数据库。</li><li><strong>分发</strong>：用 <strong>CDN</strong> 就近分发，减轻源站压力；热门内容预热到边缘节点。</li><li><strong>上传</strong>：<strong>分片上传 + 断点续传</strong>，大文件切片并行上传，失败只重传分片；上传后做<strong>多码率转码</strong>（不同分辨率/码率）和内容审核。</li><li><strong>播放</strong>：<strong>自适应码率</strong>（HLS / DASH）按网络状况切换清晰度，支持<strong>断点续传</strong>和拖动，首帧优化靠预加载与边下边播。</li><li><strong>元数据</strong>：读写分离 + 缓存扛读。</li></ul><p>一句话结论：视频系统的核心是「<strong>对象存储 + CDN + 多码率转码</strong>」，CDN 就近分发减轻源站压力，多码率适配不同网络。</p><hr><h2 id="_20-实时统计-dau-wau-mau-bitmap-★★★" tabindex="-1">20. 实时统计 DAU/WAU/MAU（Bitmap）★★★ <a class="header-anchor" href="#_20-实时统计-dau-wau-mau-bitmap-★★★" aria-label="Permalink to &quot;20. 实时统计 DAU/WAU/MAU（Bitmap）★★★&quot;">​</a></h2><p>用 <strong>Redis Bitmap</strong>：一个用户占一个 <strong>bit</strong> 位，用户 id 作为偏移量。</p><ul><li>记录当天活跃：<code>setbit key user_id 1</code>；</li><li>统计当天活跃数：<code>bitcount key</code>；</li><li>周活 / 月活：把多天的 bitmap 用 <code>bitop OR</code> 求并集，再 <code>bitcount</code>，天然去重。</li></ul><p>优点是<strong>极省内存</strong>（1 亿用户约 12MB）、天然去重、位运算快。前提是用户 id 能映射成<strong>连续整数</strong>；如果 id 稀疏（大量空洞）或量级远超实际用户数，Bitmap 反而浪费空间，应改用 <strong>HyperLogLog</strong>。</p><hr><h2 id="_21-统计网站每个网页的-uv-hyperloglog-★★★" tabindex="-1">21. 统计网站每个网页的 UV（HyperLogLog）★★★ <a class="header-anchor" href="#_21-统计网站每个网页的-uv-hyperloglog-★★★" aria-label="Permalink to &quot;21. 统计网站每个网页的 UV（HyperLogLog）★★★&quot;">​</a></h2><p><strong>HyperLogLog</strong> 是<strong>概率数据结构</strong>，用固定极小的内存（每个 key 约 <strong>12KB</strong>）估算集合的<strong>基数</strong>（独立元素个数），<strong>标准误差约 0.81%</strong>。</p><ul><li>每个网页每天一个 key：<code>pfadd key visitor_id</code> 记录访客，<code>pfcount key</code> 得到 UV，多个 key 可用 <code>pfmerge</code> 合并。</li><li>原理：基于哈希后前导零的最大长度估计基数，并用分桶求调和平均降低方差，所以内存固定、与元素数量无关。</li><li>相比 Set 精确去重，它是用「<strong>近似值</strong>」换「<strong>固定的小内存</strong>」；不支持删除单个元素（可覆盖重建）。</li></ul><p>选型：id 连续且范围可控用 <strong>Bitmap</strong>；稀疏、超大基数去重用 <strong>HyperLogLog</strong>；必须精确再用 <strong>Set</strong>（内存随元素线性增长）。</p><hr><h2 id="_22-10-亿数量高效排序-外部排序-★★☆" tabindex="-1">22. 10 亿数量高效排序（外部排序）★★☆ <a class="header-anchor" href="#_22-10-亿数量高效排序-外部排序-★★☆" aria-label="Permalink to &quot;22. 10 亿数量高效排序（外部排序）★★☆&quot;">​</a></h2><p>内存装不下时用<strong>外部归并排序</strong>，分治 + 归并：</p><ol><li><strong>分块</strong>：按内存容量把大文件切成若干块，每块读入内存排好序后写回临时有序文件。</li><li><strong>多路归并</strong>：用<strong>小顶堆</strong>维护每一路当前最小元素，每次取堆顶输出并补充该路的下一个元素，把多个有序块合并成一个有序大文件。</li><li><strong>优化</strong>：增大块大小以减少归并路数、多路并行归并、顺序读写减少随机 IO。</li></ol><p>瓶颈在<strong>磁盘 IO</strong> 而不是比较次数，所以优化方向是减少 IO 次数、提升顺序读。这种量级的统计排序通常直接用 <strong>ClickHouse</strong>、InfluxDB 这类引擎，不必自己实现外部排序。</p><hr><h2 id="_23-为什么要系统拆分、如何拆分-★★★" tabindex="-1">23. 为什么要系统拆分、如何拆分 ★★★ <a class="header-anchor" href="#_23-为什么要系统拆分、如何拆分-★★★" aria-label="Permalink to &quot;23. 为什么要系统拆分、如何拆分 ★★★&quot;">​</a></h2><p>单体随业务变大的问题：编译部署慢、代码耦合、团队协作冲突、<strong>故障影响面大</strong>（一处 OOM 全站挂）、无法按模块<strong>独立扩容</strong>。</p><p>拆分收益：独立部署、独立扩展、<strong>故障隔离</strong>、团队职责和技术栈清晰。</p><p>怎么拆：</p><ul><li>按<strong>业务域</strong>拆（识别核心领域与边界，参考 <strong>DDD 限界上下文</strong>），而不是按技术分层拆；</li><li>每个服务<strong>独立数据库</strong>，避免共享库造成隐性耦合；</li><li>先拆<strong>边缘、耦合低</strong>的服务，核心链路最后动；</li><li>配套<strong>注册中心、配置中心、网关、链路追踪、监控告警</strong>，否则拆完更难排查；</li><li>拆分代价是<strong>跨服务一致性</strong>、分布式事务、联调和运维成本上升，所以要避免<strong>过度拆</strong>；小规模先单体，规模到了再拆，粒度与团队规模匹配。</li></ul><hr><h2 id="_24-为什么做分库分表-★★☆" tabindex="-1">24. 为什么做分库分表 ★★☆ <a class="header-anchor" href="#_24-为什么做分库分表-★★☆" aria-label="Permalink to &quot;24. 为什么做分库分表 ★★☆&quot;">​</a></h2><p>单表到千万行级别后：查询变慢、索引维护成本高、DDL 锁表时间长；单库则受连接数、磁盘容量、IO 上限约束。<strong>分库分表</strong>是横向扩展手段，让每个库/表的数据量和压力变小。</p><ul><li><strong>垂直拆分</strong>：按业务或字段拆，把不常用的大字段拆出去，或按业务域分库。</li><li><strong>水平拆分</strong>：同一张表按分片键（如用户 id、订单号）散到多个库/表，结构一致。</li></ul><p>代价是<strong>分布式事务</strong>、<strong>跨库 join</strong> 和分页、<strong>分布式主键</strong>、路由与扩容复杂度、跨片聚合统计。</p><p>所以它是最后手段，演进顺序是：<strong>索引优化 → 缓存 → 读写分离 → 分库分表</strong>。数据量未到瓶颈前，用索引优化、冷热归档、读写分离通常就能撑住。</p><hr><h2 id="_25-分布式幂等性如何设计" tabindex="-1">25. 分布式幂等性如何设计？ <a class="header-anchor" href="#_25-分布式幂等性如何设计" aria-label="Permalink to &quot;25. 分布式幂等性如何设计？&quot;">​</a></h2><p>在高并发场景的架构里，幂等性是必须得保证的。比如说支付功能，用户发起支付，如果后台没有做幂等校验，刚好用户手抖多点了几下，于是后台就可能多次受到同一个订单请求，不做幂等很容易就让用户重复支付了，这样用户是肯定不能忍的。</p><p>解决方案</p><p>1，查询和删除不在幂等讨论范围，查询肯定没有幂等的说，删除：第一次删除成功后，后面来删除直接返回0，也是返回成功。</p><p>2，建唯一索引：唯一索引或唯一组合索引来防止新增数据存在脏数据 （当表存在唯一索引，并发时新增异常时，再查询一次就可以了，数据应该已经存在了，返回结果即可）。</p><p>3，token机制：由于重复点击或者网络重发，或者nginx重发等情况会导致数据被重复提交。前端在数据提交前要向后端服务的申请token，token放到 Redis 或 JVM 内存，token有效时间。提交后</p><p>后台校验token，同时删除token，生成新的token返回。 redis要用删除操作来判断token，删除成功代表token校验通过，如果用select+delete来校验token，存在并发问题，不建议使用。</p><p>select id ,name from table_# where id= &#39;##&#39; for update;</p><p>InnoDB 存储引擎，那么就会出现锁全表）。悲观锁使用时一般伴随事务一起使用，数据锁定时间可能会很长，根据实际情况选用（另外还要考虑id是否为主键，如果id不是主键或者不是</p><p>5，乐观锁，给数据库表增加一个version字段，可以通过这个字段来判断是否已经被修改了</p><p>update table_xxx set name=#name#,version=version+1 where version=#version#</p><p>6，分布式锁，比如Redis、Zookeeper 的分布式锁。单号为key，然后给Key设置有效期（防止支付失败后，锁一直不释放），来一个请求使用订单号生成一把锁，业务代码执行完成后再释放锁。</p><p>7，保底方案，先查询是否存在此单，不存在进行支付，存在就直接返回支付结果。</p><h2 id="_26-2-简单一次完整的-http-请求所经历的步骤" tabindex="-1">26. 2，简单一次完整的 HTTP 请求所经历的步骤？ <a class="header-anchor" href="#_26-2-简单一次完整的-http-请求所经历的步骤" aria-label="Permalink to &quot;26. 2，简单一次完整的 HTTP 请求所经历的步骤？&quot;">​</a></h2><p>IP 地址，递归搜索)。1、DNS 解析(通过访问的域名找出其</p><p>2、 HTTP 请求，当输入一个请求时，建立一个 Socket 连接发起 TCP的 3 次握手。</p><p>如果是 HTTPS 请求，会略微有不同。等到 HTTPS 小节，我们在来讲。</p><p>3.1、客户端向服务器发送请求命令（一般是 GET 或 POST 请求）。</p><p>这个是补充内容，面试一般不用回答。</p><p>客户端的网络层不用关心应用层或者传输层的东西，主要做的是通过查找路由表确定如何到达服务器，期间可能经过多个路由器，这些都是由路由器来完成的工作，我不作过多的描述，无非就是通过查找路由表决定通过那个路径到达服务器。</p><p>客户端的链路层，包通过链路层发送到路由器，通过邻居协议查找给定 IP 地址的 MAC 地址，然后发送 ARP 请求查找目的地址，如果得到回应后就可以使用 ARP 的请求应答交换的 IP 数据包现在就可以传输了，然后发送 IP 数据包到达服务器的地址。</p><p>3.2、客户端发送请求头信息和数据。</p><p>4.1、服务器发送应答头信息。</p><p>4.2、服务器向客户端发送数据。</p><p>5、服务器关闭 TCP 连接（4次挥手）。</p><p>这里是否关闭 TCP 连接，也根据 HTTP Keep-Alive 机制有关。</p><p>同时，客户端也可以主动发起关闭 TCP 连接。</p><p>6、客户端根据返回的CSS、HTML、JS 进行渲染。</p><p><img src="'+p+'" alt="img"></p><h2 id="_27-说说你对分布式事务的了解" tabindex="-1">27. 说说你对分布式事务的了解 <a class="header-anchor" href="#_27-说说你对分布式事务的了解" aria-label="Permalink to &quot;27. 说说你对分布式事务的了解&quot;">​</a></h2><p>分布式事务是企业集成中的一个技术难点，也是每一个分布式系统架构中都会涉及到的一个东西， 特别是在微服务架构中，几乎可以说是无法避免。</p><p>首先要搞清楚：ACID、CAP、 BASE理论。</p><p>ACID</p><p>指数据库事务正确执行的四个基本要素：</p><ol><li><p>原子性（Atomicity）</p></li><li><p>一致性（Consistency）</p></li><li><p>隔离性（Isolation ）</p></li><li><p>持久性（Durability）</p></li></ol><p>CAP</p><p>CAP原则又称CAP定理，指的是在一个分布式系统中，一致性（Consistency）、可用性</p><p>（Availability）、分区容忍性（Partition tolerance）。 CAP 原则指的是，这三个要素最多只能同时实现两点，不可能三者兼顾。</p><p>一致性：在分布式系统中的所有数据备份，在同一时刻是否同样的值。</p><p>可用性：在集群中一部分节点故障后，集群整体是否还能响应客户端的读写请求。</p><p>分区容忍性：以实际效果而言，分区相当于对通信的时限要求。系统如果不能在时限内达成数据一致性，就意味着发生了分区的情况，必须就当前操作在C和A之间做出选择。</p><p>BASE理论</p><p>BASE理论是对CAP中的一致性和可用性进行一个权衡的结果，理论的核心思想就是：我们无法做到强一致，但每个应用都可以根据自身的业务特点，采用适当的方式来使系统达到最终一致性。</p><p>Basically Available（基本可用）</p><p>Soft state（软状态）</p><p>Eventually consistent（最终一致性）</p><h2 id="_28-你知道哪些分布式事务解决方案" tabindex="-1">28. 你知道哪些分布式事务解决方案？ <a class="header-anchor" href="#_28-你知道哪些分布式事务解决方案" aria-label="Permalink to &quot;28. 你知道哪些分布式事务解决方案？&quot;">​</a></h2><p>我目前知道的有五种：</p><ol><li><p>两阶段提交(2PC)</p></li><li><p>三阶段提交(3PC)</p></li><li><p>补偿事务(TCC=Try-Conﬁrm-Cancel)</p></li><li><p>本地消息队列表(MQ)</p></li><li><p>Sagas事务模型(最终一致性)</p></li></ol><p>说完上面五种，面试官一般都会继续问下面这几个问题（可能就问一两个，也可能全部问）。</p><h2 id="_29-5-什么是二阶段提交" tabindex="-1">29. 5，什么是二阶段提交？ <a class="header-anchor" href="#_29-5-什么是二阶段提交" aria-label="Permalink to &quot;29. 5，什么是二阶段提交？&quot;">​</a></h2><p>两阶段提交2PC是分布式事务中最强大的事务类型之一，两段提交就是分两个阶段提交：</p><p>第一阶段询问各个事务数据源是否准备好。</p><p>. 第二阶段才真正将数据提交给事务数据源。</p><p>为了保证该事务可以满足ACID，就要引入一个协调者（Cooradinator）。其他的节点被称为参与者 （Participant）。协调者负责调度参与者的行为，并最终决定这些参与者是否要把事务进行提交。</p><p>处理流程如下：</p><p><img src="'+i+'" alt="img"></p><p>阶段一</p><p>a) 协调者向所有参与者发送事务内容，询问是否可以提交事务，并等待答复。</p><p>b) 各参与者执行事务操作，将 undo 和 redo 信息记入事务日志中（但不提交事务）。</p><p>c) 如参与者执行成功，给协调者反馈 yes，否则反馈 no。</p><p>阶段二</p><p>如果协调者收到了参与者的失败消息或者超时，直接给每个参与者发送回滚(rollback)消息；否则， 发送提交(commit)消息。两种情况处理如下：</p><p>情况1：当所有参与者均反馈 yes，提交事务</p><p>a) 协调者向所有参与者发出正式提交事务的请求（即 commit 请求）。</p><p>b) 参与者执行 commit 请求，并释放整个事务期间占用的资源。</p><p>c) 各参与者向协调者反馈 ack(应答)完成的消息。</p><p>d) 协调者收到所有参与者反馈的 ack 消息后，即完成事务提交。</p><p>情况2：当有一个参与者反馈 no，回滚事务</p><p>a) 协调者向所有参与者发出回滚请求（即 rollback 请求）。</p><p>b) 参与者使用阶段 1 中的 undo 信息执行回滚操作，并释放整个事务期间占用的资源。</p><p>c) 各参与者向协调者反馈 ack 完成的消息。</p><p>d) 协调者收到所有参与者反馈的 ack 消息后，即完成事务。</p><p>问题</p><ol><li><p>性能问题：所有参与者在事务提交阶段处于同步阻塞状态，占用系统资源，容易导致性能瓶颈。</p></li><li><p>可靠性问题：如果协调者存在单点故障问题，或出现故障，提供者将一直处于锁定状态。</p></li><li><p>数据一致性问题：在阶段 2 中，如果出现协调者和参与者都挂了的情况，有可能导致数据不一 致。</p></li></ol><p>优点：尽量保证了数据的强一致，适合对数据强一致要求很高的关键领域。（其实也不能100%保证强一致）。</p><p>缺点：实现复杂，牺牲了可用性，对性能影响较大，不适合高并发高性能场景。</p><p><strong>补充（原文详解）</strong></p><p>三阶段提交是在二阶段提交上的改进版本，3PC最关键要解决的就是协调者和参与者同时挂掉的问题，所以3PC把2PC的准备阶段再次一分为二，这样三阶段提交。</p><p>处理流程如下：</p><p>阶段一</p><p>a) 协调者向所有参与者发出包含事务内容的 canCommit 请求，询问是否可以提交事务，并等待所有参与者答复。</p><p>b) 参与者收到 canCommit 请求后，如果认为可以执行事务操作，则反馈 yes 并进入预备状态，否则反馈 no。</p><p>阶段二</p><p>协调者根据参与者响应情况，有以下两种可能。</p><p>情况1：所有参与者均反馈 yes，协调者预执行事务</p><p>a) 协调者向所有参与者发出 preCommit 请求，进入准备阶段。</p><p>b) 参与者收到 preCommit 请求后，执行事务操作，将 undo 和 redo 信息记入事务日志中（但不提交事务）。</p><p>c) 各参与者向协调者反馈 ack 响应或 no 响应，并等待最终指令。</p><p>情况2：只要有一个参与者反馈 no，或者等待超时后协调者尚无法收到所有提供者的反馈，即中断事务</p><p>a) 协调者向所有参与者发出 abort 请求。</p><p>b) 无论收到协调者发出的 abort 请求，或者在等待协调者请求过程中出现超时，参与者均会中断事务。</p><p>阶段三</p><p>该阶段进行真正的事务提交，也可以分为以下两种情况。</p><p>情况 1：所有参与者均反馈 ack 响应，执行真正的事务提交</p><p>a) 如果协调者处于工作状态，则向所有参与者发出 do Commit 请求。</p><p>b) 参与者收到 do Commit 请求后，会正式执行事务提交，并释放整个事务期间占用的资源。</p><p>c) 各参与者向协调者反馈 ack 完成的消息。</p><p>d) 协调者收到所有参与者反馈的 ack 消息后，即完成事务提交。</p><p>情况2：只要有一个参与者反馈 no，或者等待超时后协调组尚无法收到所有提供者的反馈，即回滚事务。</p><p>a) 如果协调者处于工作状态，向所有参与者发出 rollback 请求。</p><p>b) 参与者使用阶段 1 中的 undo 信息执行回滚操作，并释放整个事务期间占用的资源。</p><p>c) 各参与者向协调组反馈 ack 完成的消息。</p><p>d) 协调组收到所有参与者反馈的 ack 消息后，即完成事务回滚。</p><p>优点：相比二阶段提交，三阶段提交降低了阻塞范围，在等待超时后协调者或参与者会中断事务。 避免了协调者单点问题。阶段 3 中协调者出现问题时，参与者会继续提交事务。</p><p>缺点：数据不一致问题依然存在，当在参与者收到 preCommit 请求后等待 do commite 指令时， 此时如果协调者请求中断事务，而协调者无法与参与者正常通信，会导致参与者继续提交事务，造成数据不一致。</p><h2 id="_30-什么是补偿事务" tabindex="-1">30. 什么是补偿事务？ <a class="header-anchor" href="#_30-什么是补偿事务" aria-label="Permalink to &quot;30. 什么是补偿事务？&quot;">​</a></h2><p>TCC （ Try Conﬁrm Cancel）是服务化的二阶段编程模型，采用的补偿机制：</p><p><img src="'+s+'" alt="img"></p><p>TCC 其实就是采用的补偿机制，其核心思想是：针对每个操作，都要注册一个与其对应的确认和补偿（撤销）操作。</p><p>它分为三个步骤：</p><p>Try 阶段主要是对业务系统做检测及资源预留。</p><p>Conﬁrm 阶段主要是对业务系统做确认提交，Try阶段执行成功并开始执行 Conﬁrm阶段时，默认 Conﬁrm阶段是不会出错的。即：只要Try成功，Conﬁrm一定成功。</p><p>Cancel 阶段主要是在业务执行错误，需要回滚的状态下执行的业务取消，预留资源释放。</p><p>举个例子，假入你要向老田转账，思路大概是： 我们有一个本地方法，里面依次调用步骤： 1、</p><p>首先在 Try 阶段，要先调用远程接口把你和老田的钱给冻结起来。 2、在 Conﬁrm 阶段，执行远程调用的转账的操作，转账成功进行解冻。 3、如果第2步执行成功，那么转账成功，如果第二步执行失败，则调用远程冻结接口对应的解冻方法 (Cancel)。</p><p>优点：</p><p>性能提升：具体业务来实现控制资源锁的粒度变小，不会锁定整个资源。</p><p>数据最终一致性：基于 Conﬁrm 和 Cancel 的幂等性，保证事务最终完成确认或者取消，保证数据的一致性。</p><p>可靠性：解决了 XA 协议的协调者单点故障问题，由主业务方发起并控制整个业务活动，业务活动管理器也变成多点，引入集群。</p><p>缺点：TCC 的 Try、Conﬁrm 和 Cancel 操作功能要按具体业务来实现，业务耦合度较高，提高了开发成本。</p><h2 id="_31-消息队列是怎么实现的" tabindex="-1">31. 消息队列是怎么实现的？ <a class="header-anchor" href="#_31-消息队列是怎么实现的" aria-label="Permalink to &quot;31. 消息队列是怎么实现的？&quot;">​</a></h2><p>本地消息表（异步确保）</p><p>本地消息表这种实现方式应该是业界使用最多的，其核心思想是将分布式事务拆分成本地事务进行处理，这种思路是来源于ebay。我们可以从下面的流程图中看出其中的一些细节：</p><p><img src="'+e+'" alt="img"></p><p>基本思路就是：</p><p>消息生产方，需要额外建一个消息表，并记录消息发送状态。消息表和业务数据要在一个事务里提交，也就是说他们要在一个数据库里面。然后消息会经过MQ发送到消息的消费方。如果消息发送失败，会进行重试发送。</p><p>消息消费方，需要处理这个消息，并完成自己的业务逻辑。此时如果本地事务处理成功，表明已经处理成功了，如果处理失败，那么就会重试执行。如果是业务上面的失败，可以给生产方发送一个业务补偿消息，通知生产方进行回滚等操作。</p><p>生产方和消费方定时扫描本地消息表，把还没处理完成的消息或者失败的消息再发送一遍。如果有靠谱的自动对账补账逻辑，这种方案还是非常实用的。</p><p>这种方案遵循BASE理论，采用的是最终一致性，笔者认为是这几种方案里面比较适合实际业务场景的，即不会出现像2PC那样复杂的实现(当调用链很长的时候，2PC的可用性是非常低的)，也不会像 TCC那样可能出现确认或者回滚不了的情况。</p><p>优点： 一种非常经典的实现，避免了分布式事务，实现了最终一致性。在 .NET中有现成的解决方案。</p><p>缺点： 消息表会耦合到业务系统中，如果没有封装好的解决方案，会有很多杂活需要处理。</p><p>MQ 事务消息</p><p>有一些第三方的MQ是支持事务消息的，比如RocketMQ，他们支持事务消息的方式也是类似于采用的二阶段提交，但是市面上一些主流的MQ都是不支持事务消息的，比如 RabbitMQ 和 Kafka 都不支持。</p><p>以阿里的 RocketMQ 中间件为例，其思路大致为：</p><p>第一阶段Prepared消息，会拿到消息的地址。 第二阶段执行本地事务，第三阶段通过第一阶段拿到的地址去访问消息，并修改状态。</p><p>也就是说在业务方法内要想消息队列提交两次请求，一次发送消息和一次确认消息。如果确认消息发送失败了RocketMQ会定期扫描消息集群中的事务消息，这时候发现了Prepared消息，它会向消息发送者确认，所以生产方需要实现一个check接口，RocketMQ会根据发送端设置的策略来决定是回滚还是继续发送确认消息。这样就保证了消息发送与本地事务同时成功或同时失败。</p><p><img src="'+l+'" alt="img"></p><p>遗憾的是，RocketMQ并没有 .NET 客户端。有关 RocketMQ的更多消息，大家可以查看这篇博客</p><p>优点： 实现了最终一致性，不需要依赖本地数据库事务。</p><p>缺点： 实现难度大，主流MQ不支持，没有.NET客户端，RocketMQ事务消息部分代码也未开源。</p><h2 id="_32-那你说说sagas事务模型" tabindex="-1">32. 那你说说Sagas事务模型 <a class="header-anchor" href="#_32-那你说说sagas事务模型" aria-label="Permalink to &quot;32. 那你说说Sagas事务模型&quot;">​</a></h2><p>Saga模式是一种分布式异步事务，一种最终一致性事务，是一种柔性事务，有两种不同的方式来实现saga事务，最流行的两种方式是：</p><p>一、 事件/编排Choreography：没有中央协调器（没有单点风险）时，每个服务产生并聆听其他服务的事件，并决定是否应采取行动。</p><p>该实现第一个服务执行一个事务，然后发布一个事件。该事件被一个或多个服务进行监听，这些服务再执行本地事务并发布（或不发布）新的事件，当最后一个服务执行本地事务并且不发布任何事件时，意味着分布式事务结束，或者它发布的事件没有被任何Saga参与者听到都意味着事务结束。</p><p><img src="'+g+'" alt="img"></p><p>处理流程说明：</p><p>订单服务保存新订单，将状态设置为pengding挂起状态，并发布名为ORDER_CREATED_EVENT的事件。</p><p>支付服务监听ORDER_CREATED_EVENT，并公布事件BILLED_ORDER_EVENT。</p><p>库存服务监听BILLED_ORDER_EVENT，更新库存，并发布ORDER_PREPARED_EVENT。</p><p>货运服务监听ORDER_PREPARED_EVENT，然后交付产品。最后，它发布</p><p>ORDER_DELIVERED_EVENT。</p><p>最后，订单服务侦听ORDER_DELIVERED_EVENT并设置订单的状态为concluded完成。</p><p>假设库存服务在事务过程中失败了。进行回滚：</p><p>库存服务产生PRODUCT_OUT_OF_STOCK_EVENT</p><p>订购服务和支付服务会监听到上面库存服务的这一事件：</p><p>①支付服务会退款给客户。</p><p>②订单服务将订单状态设置为失败。</p><p>优点：事件/编排是实现Saga模式的自然方式; 它很简单，容易理解，不需要太多的努力来构建，所有参与者都是松散耦合的，因为他们彼此之间没有直接的耦合。如果您的事务涉及2至4个步骤，则可能是非常合适的。</p><p>二、 命令/协调orchestrator：中央协调器负责集中处理事件的决策和业务逻辑排序。</p><p>saga协调器orchestrator以命令/回复的方式与每项服务进行通信，告诉他们应该执行哪些操作。</p><p><img src="'+d+'" alt="img"></p><p>订单服务保存pending状态，并要求订单Saga协调器（简称OSO）开始启动订单事务。</p><p>OSO向收款服务发送执行收款命令，收款服务回复Payment Executed消息。</p><p>OSO向库存服务发送准备订单命令，库存服务将回复OrderPrepared消息。</p><p>OSO向货运服务发送订单发货命令，货运服务将回复Order Delivered消息。</p><p>OSO订单Saga协调器必须事先知道执行“创建订单”事务所需的流程(通过读取BPM业务流程XML配置获得)。如果有任何失败，它还负责通过向每个参与者发送命令来撤销之前的操作来协调分布式的回滚。当你有一个中央协调器协调一切时，回滚要容易得多，因为协调器默认是执行正向流程，回滚时只要执行反向流程即可。</p><p>优点：</p><p>避免服务之间的循环依赖关系，因为saga协调器会调用saga参与者，但参与者不会调用协调器。</p><p>集中分布式事务的编排。</p><p>只需要执行命令/回复(其实回复消息也是一种事件消息)，降低参与者的复杂性。</p><p>在添加新步骤时，事务复杂性保持线性，回滚更容易管理。</p><p>如果在第一笔交易还没有执行完，想改变有第二笔事务的目标对象，则可以轻松地将其暂停在协调器上，直到第一笔交易结束。</p><h2 id="_33-11-幂等解决方法有哪些" tabindex="-1">33. 11，幂等解决方法有哪些？ <a class="header-anchor" href="#_33-11-幂等解决方法有哪些" aria-label="Permalink to &quot;33. 11，幂等解决方法有哪些？&quot;">​</a></h2><p>什么是幂等？</p><p>常见描述：对于相同的请求应该返回相同的结果，所以查询类接口是天然的幂等性接口。</p><p>真正的回答方式：幂等指的是相同请求（identical request）执行一次或者多次所带来的副作用（side-eﬀects）是一样的。</p><p>什么常见会出现幂等？</p><p>前端调后端接口发起支付超时，然后再次发起重试。可能会导致多次支付。</p><p>Dubbo中也有重试机制。</p><p>页面上多次点击。</p><p>我们想要的是：接口的幂等性实际上就是接口可重复调用，在调用方多次调用的情况下，接口最终得到的结果是一致的。</p><p>解决方案</p><p>在插入数据的时候，插入去重表，利用数据库的唯一索引特性，保证唯一的逻辑。</p><p>悲观锁，select for update，整个执行过程中锁定该订单对应的记录。注意：这种在DB读大于写的情况下尽量少用。</p><p>先查询后修改数据，并发不高的后台系统，或者一些任务JOB，为了支持幂等，支持重复执行，简单的处理方法是，先查询下一些关键数据，判断是否已经执行过，在进行业务处理，就可以了。注意：核心高并发流程不要用这种方法。</p><p>状态机幂等，在设计单据相关的业务，或者是任务相关的业务，肯定会涉及到状态机，就是业务单据上面有个状态，状态在不同的情况下会发生变更，一般情况下存在有限状态机，这时候，如果状态机已经处于下一个状态，这时候来了一个上一个状态的变更，理论上是不能够变更的，这样的</p><p>话，保证了有限状态机的幂等。</p><p>token机制，防止页面重复提交：</p><p>集群环境：采用token加redis（ redis单线程的，处理需要排队）或者</p><p>单JVM环境：采用token加redis或token加jvm内存</p><p>数据提交前要向服务的申请token，token放到redis或jvm内存，设置token有效时间，提交后后台校验token，同时删除token，生成新的token返回。token特点：要申请，一次有效性，可以限流。</p><p>全局唯一ID，如果使用全局唯一ID，就是根据业务的操作和内容生成一个全局ID，在执行操作前先根据这个全局唯一ID是否存在，来判断这个操作是否已经执行。如果不存在则把全局ID，存储到存储系统中，比如数据库、 redis等。如果存在则表示该方法已经执行。</p><h2 id="_34-12-常见负载均衡算法有哪些" tabindex="-1">34. 12，常见负载均衡算法有哪些？ <a class="header-anchor" href="#_34-12-常见负载均衡算法有哪些" aria-label="Permalink to &quot;34. 12，常见负载均衡算法有哪些？&quot;">​</a></h2><h2 id="_35-你知道哪些限流算法" tabindex="-1">35. 你知道哪些限流算法？ <a class="header-anchor" href="#_35-你知道哪些限流算法" aria-label="Permalink to &quot;35. 你知道哪些限流算法？&quot;">​</a></h2><p>限流算法有四种常见算法：</p><p>计数器算法（固定窗口）</p><p>滑动窗口</p><p>漏桶算法</p><p>令牌桶算法</p><h2 id="_36-说说什么是计数器-固定窗口-算法" tabindex="-1">36. 说说什么是计数器（固定窗口）算法 <a class="header-anchor" href="#_36-说说什么是计数器-固定窗口-算法" aria-label="Permalink to &quot;36. 说说什么是计数器（固定窗口）算法&quot;">​</a></h2><p>计数器算法是使用计数器在周期内累加访问次数，当达到设定的限流值时，触发限流策略。下一个周期开始时，进行清零，重新计数。</p><p>此算法在单机还是分布式环境下实现都非常简单，使用redis的incr原子自增性和线程安全即可轻松实现。</p><p>这个算法通常用于QPS限流和统计总访问量，对于秒级以上的时间周期来说，会存在一个非常严重的问题，那就是临界问题，如下图：</p><p><img src="'+h+'" alt="img"></p><p>假设1min内服务器的负载能力为100，因此一个周期的访问量限制在100，然而在第一个周期的最后5秒和下一个周期的开始5秒时间段内，分别涌入100的访问量，虽然没有超过每个周期的限制</p><p>量，但是整体上10秒内已达到200的访问量，已远远超过服务器的负载能力，由此可见，计数器算法方式限流对于周期比较长的限流，存在很大的弊端。</p><h2 id="_37-说说什么是滑动窗口算法" tabindex="-1">37. 说说什么是滑动窗口算法 <a class="header-anchor" href="#_37-说说什么是滑动窗口算法" aria-label="Permalink to &quot;37. 说说什么是滑动窗口算法&quot;">​</a></h2><p>滑动窗口算法是将时间周期分为N个小周期，分别记录每个小周期内访问次数，并且根据时间滑动删除过期的小周期。</p><p>如下图，假设时间周期为1min，将1min再分为2个小周期，统计每个小周期的访问数量，则可以看到，第一个时间周期内，访问数量为75，第二个时间周期内，访问数量为100，超过100的访问则被限流掉了</p><p><img src="'+c+'" alt="img"></p><p>由此可见，当滑动窗口的格子划分的越多，那么滑动窗口的滚动就越平滑，限流的统计就会越精确。</p><p>此算法可以很好的解决固定窗口算法的临界问题。</p><h2 id="_38-说说什么是漏桶算法" tabindex="-1">38. 说说什么是漏桶算法 <a class="header-anchor" href="#_38-说说什么是漏桶算法" aria-label="Permalink to &quot;38. 说说什么是漏桶算法&quot;">​</a></h2><p>漏桶算法是访问请求到达时直接放入漏桶，如当前容量已达到上限（限流值），则进行丢弃（触发限流策略）。漏桶以固定的速率进行释放访问请求（即请求通过），直到漏桶为空。</p><p><img src="'+u+'" alt="img"></p><p><strong>补充（原文详解）</strong></p><p>令牌桶算法是程序以r（ r=时间周期/限流值）的速度向令牌桶中增加令牌，直到令牌桶满，请求到</p><p>达时向令牌桶请求令牌，如获取到令牌则通过请求，否则触发限流策略</p><p><img src="'+b+'" alt="img"></p><h2 id="_39-数据库如何处理海量数据" tabindex="-1">39. 数据库如何处理海量数据？ <a class="header-anchor" href="#_39-数据库如何处理海量数据" aria-label="Permalink to &quot;39. 数据库如何处理海量数据？&quot;">​</a></h2><p>对数据库进行：分库分表，主从架构，读写分离。</p><p>水平分库/分表，垂直分库/分表。</p><p>水平分库/表，各个库和表的结构一模一样。</p><p>垂直分库/表，各个库和表的结构不一样。</p><p>读写分离：主机负责写，从机负责读。</p><h2 id="_40-如何将长链接转换成短链接-并发送短信" tabindex="-1">40. 如何将长链接转换成短链接，并发送短信？ <a class="header-anchor" href="#_40-如何将长链接转换成短链接-并发送短信" aria-label="Permalink to &quot;40. 如何将长链接转换成短链接，并发送短信？&quot;">​</a></h2><p>短 URL 从生成到使用分为以下几步：</p><p>有一个服务,将要发送给你的长 URL 对应到一个短 URL 上.例如 www.baidu.com -&gt; www.t.cn/ 1。</p><p>把短 url 拼接到短信等的内容上发送。</p><p>用户点击短 URL ,浏览器用 301 / 302 进行重定向,访问到对应的长 URL。</p><p>展示对应的内容。</p><h2 id="_41-长链接和短链接如何互相转换" tabindex="-1">41. 长链接和短链接如何互相转换？ <a class="header-anchor" href="#_41-长链接和短链接如何互相转换" aria-label="Permalink to &quot;41. 长链接和短链接如何互相转换？&quot;">​</a></h2><p>思路是建立一个发号器。每次有一个新的长 URL 进来，我们就增加一。并且将新的数值返回 .第一个来的 url 返回&quot;www.x.cn/0&quot;,第二个返回&quot;www.x.cn/1&quot;。</p><h2 id="_42-长链接和短链接的对应关系如何存储" tabindex="-1">42. 长链接和短链接的对应关系如何存储？ <a class="header-anchor" href="#_42-长链接和短链接的对应关系如何存储" aria-label="Permalink to &quot;42. 长链接和短链接的对应关系如何存储？&quot;">​</a></h2><p>如果数据量小且 QPS 低，直接使用数据库的自增主键就可以实现。 还可以将最近/最热门的对应关系存储在 K-V 数据库中,这样子可以节省空间的同时,加快响应速度。</p><h2 id="_43-如何提高系统的并发能力" tabindex="-1">43. 如何提高系统的并发能力？ <a class="header-anchor" href="#_43-如何提高系统的并发能力" aria-label="Permalink to &quot;43. 如何提高系统的并发能力？&quot;">​</a></h2><p>使用分布式系统。</p><p>部署多台服务器，并做负载均衡。</p><p>使用缓存（Redis）集群。</p><p>数据库分库分表 + 读写分离。</p><p>引入消息中间件集群。</p><h2 id="_44-什么是springcloud" tabindex="-1">44. 什么是SpringCloud <a class="header-anchor" href="#_44-什么是springcloud" aria-label="Permalink to &quot;44. 什么是SpringCloud&quot;">​</a></h2><p>Spring cloud 流应用程序启动器是基于 Spring Boot 的 Spring 集成应用程序，提供与外部系统的集成。Spring cloud Task，一个生命周期短暂的微服务框架，用于快速构建执行有限数据处理的应用程序。</p><p><strong>补充（原文详解）</strong></p><p>使用 Spring Boot 开发分布式微服务时，我们面临以下问题</p><p>（ 1）与分布式系统相关的复杂性-这种开销包括网络问题，延迟开销，带宽问题，安全问题。</p><p>（ 2）服务发现-服务发现工具管理群集中的流程和服务如何查找和互相交谈。它涉及一个服务目录，在该目录中注册服务，然后能够查找并连接到该目录中的服务。</p><p>（ 3）冗余-分布式系统中的冗余问题。</p><p>（ 4）负载平衡 --负载平衡改善跨多个计算资源的工作负荷，诸如计算机，计算机集群，网络链路， 中央处理单元，或磁盘驱动器的分布。</p><p>（ 5）性能-问题由于各种运营开销导致的性能问题。</p><p>（ 6）部署复杂性-Devops 技能的要求。</p><h2 id="_45-什么是微服务" tabindex="-1">45. 什么是微服务 <a class="header-anchor" href="#_45-什么是微服务" aria-label="Permalink to &quot;45. 什么是微服务&quot;">​</a></h2><p>微服务架构是一种架构模式或者说是一种架构风格，它提倡将单一应用程序划分为一组小的服务， 每个服务运行在其独立的自己的进程中，服务之间相互协调、互相配合，为用户提供最终价值。服务之间采用轻量级的通信机制互相沟通（通常是基于HTTP的RESTful API）,每个服务都围绕着具体的业务进行构建，并且能够被独立的构建在生产环境、类生产环境等。另外，应避免统一的、集中</p><p>式的服务管理机制，对具体的一个服务而言，应根据业务上下文，选择合适的语言、工具对其进行构建，可以有一个非常轻量级的集中式管理来协调这些服务，可以使用不同的语言来编写服务，也可以使用不同的数据存储。</p><h2 id="_46-什么是服务熔断-什么是服务降级" tabindex="-1">46. 什么是服务熔断？什么是服务降级？ <a class="header-anchor" href="#_46-什么是服务熔断-什么是服务降级" aria-label="Permalink to &quot;46. 什么是服务熔断？什么是服务降级？&quot;">​</a></h2><p>熔断机制是应对雪崩效应的一种微服务链路保护机制。当某个微服务不可用或者响应时间太长时， 会进行服务降级，进而熔断该节点微服务的调用，快速返回“错误”的响应信息。当检测到该节点微服务调用响应正常后恢复调用链路。在SpringCloud框架里熔断机制通过Hystrix实现，Hystrix会监控微服务间调用的状况，当失败的调用到一定阈值，缺省是5秒内调用20次，如果失败，就会启动熔断机制。</p><p>服务降级，一般是从整体负荷考虑。就是当某个服务熔断之后，服务器将不再被调用，此时客户端可以自己准备一个本地的fallback回调，返回一个缺省值。这样做，虽然水平下降，但好歹可用， 比直接挂掉强。</p><p>Hystrix相关注解 @EnableHystrix：开启熔断 @HystrixCommand(fallbackMethod=”XXX”)：声明一个失败回滚处理函数XXX，当被注解的方法执行超时（默认是1000毫秒），就会执行fallback函数，返回错误提示。</p><h2 id="_47-springboot和springcloud的区别" tabindex="-1">47. SpringBoot和SpringCloud的区别？ <a class="header-anchor" href="#_47-springboot和springcloud的区别" aria-label="Permalink to &quot;47. SpringBoot和SpringCloud的区别？&quot;">​</a></h2><p>SpringBoot专注于快速方便的开发单个个体微服务。</p><p>SpringCloud是关注全局的微服务协调整理治理框架，它将SpringBoot开发的一个个单体微服务整合并管理起来，</p><p>为各个微服务之间提供，配置管理、服务发现、断路器、路由、微代理、事件总线、全局锁、决策竞选、分布式会话等等集成服务</p><p>SpringBoot可以离开SpringCloud独立使用开发项目， 但是SpringCloud离不开SpringBoot，属于</p><p>依赖的关系.</p><p>SpringBoot专注于快速、方便的开发单个微服务个体，SpringCloud关注全局的服务治理框架。</p><h2 id="_48-负载平衡的意义什么" tabindex="-1">48. 负载平衡的意义什么？ <a class="header-anchor" href="#_48-负载平衡的意义什么" aria-label="Permalink to &quot;48. 负载平衡的意义什么？&quot;">​</a></h2><p>在计算中，负载平衡可以改善跨计算机，计算机集群，网络链接，中央处理单元或磁盘驱动器等多种计算资源的工作负载分布。负载平衡旨在优化资源使用，最大化吞吐量，最小化响应时间并避免任何单一资源的过载。使用多个组件进行负载平衡而不是单个组件可能会通过冗余来提高可靠性和可用性。负载平衡通常涉及专用软件或硬件，例如多层交换机或域名系统服务器进程。</p><h2 id="_49-什么是hystrix-它如何实现容错" tabindex="-1">49. 什么是Hystrix？它如何实现容错？ <a class="header-anchor" href="#_49-什么是hystrix-它如何实现容错" aria-label="Permalink to &quot;49. 什么是Hystrix？它如何实现容错？&quot;">​</a></h2><p>Hystrix是一个延迟和容错库，旨在隔离远程系统，服务和第三方库的访问点，当出现故障是不可避免的故障时，停止级联故障并在复杂的分布式系统中实现弹性。</p><p>通常对于使用微服务架构开发的系统，涉及到许多微服务。这些微服务彼此协作。</p><p>思考以下微服务</p><p><img src="'+_+'" alt="img"></p><p>假设如果上图中的微服务9失败了，那么使用传统方法我们将传播一个异常。但这仍然会导致整个系统崩溃。</p><p>随着微服务数量的增加，这个问题变得更加复杂。微服务的数量可以高达1000.这是hystrix出现的地方我们将使用Hystrix在这种情况下的Fallback方法功能。我们有两个服务employee-consumer 使用由employee-consumer公开的服务。</p><p>简化图如下所示</p><p>现在假设由于某种原因，employee-producer公开的服务会抛出异常。我们在这种情况下使用</p><p>Hystrix定义了一个回退方法。这种后备方法应该具有与公开服务相同的返回类型。如果暴露服务中出现异常，则回退方法将返回一些值。</p><h2 id="_50-什么是hystrix断路器-我们需要它吗" tabindex="-1">50. 什么是Hystrix断路器？我们需要它吗？ <a class="header-anchor" href="#_50-什么是hystrix断路器-我们需要它吗" aria-label="Permalink to &quot;50. 什么是Hystrix断路器？我们需要它吗？&quot;">​</a></h2><p>由于某些原因，employee-consumer公开服务会引发异常。在这种情况下使用Hystrix我们定义了一个回退方法。如果在公开服务中发生异常，则回退方法返回一些默认值。</p><p><img src="'+m+'" alt="img"></p><p>如果ﬁrstPage method() 中的异常继续发生，则Hystrix电路将中断，并且员工使用者将一起跳过</p><p>ﬁrtsPage方法，并直接调用回退方法。 断路器的目的是给第一页方法或第一页方法可能调用的其他</p><p>方法留出时间，并导致异常恢复。可能发生的情况是，在负载较小的情况下，导致异常的问题有更好的恢复机会。</p><h2 id="_51-11-eureka自我保护机制是什么" tabindex="-1">51. 11，eureka自我保护机制是什么? <a class="header-anchor" href="#_51-11-eureka自我保护机制是什么" aria-label="Permalink to &quot;51. 11，eureka自我保护机制是什么?&quot;">​</a></h2><p>当Eureka Server 节点在短时间内丢失了过多实例的连接时（比如网络故障或频繁启动关闭客户</p><p>端）节点会进入自我保护模式，保护注册信息，不再删除注册数据，故障恢复时，自动退出自我保护模式。</p><h2 id="_52-12-什么是ribbon" tabindex="-1">52. 12，什么是Ribbon？ <a class="header-anchor" href="#_52-12-什么是ribbon" aria-label="Permalink to &quot;52. 12，什么是Ribbon？&quot;">​</a></h2><p>ribbon是一个负载均衡客户端，可以很好的控制htt和tcp的一些行为。feign默认集成了ribbon。</p><h2 id="_53-13-什么是feigin-它的优点是什么" tabindex="-1">53. 13，什么是feigin？它的优点是什么？ <a class="header-anchor" href="#_53-13-什么是feigin-它的优点是什么" aria-label="Permalink to &quot;53. 13，什么是feigin？它的优点是什么？&quot;">​</a></h2><p>1.feign采用的是基于接口的注解 2.feign整合了ribbon，具有负载均衡的能力 3.整合了Hystrix，具有熔断的能力</p><p>使用: 1.添加pom依赖。 2.启动类添加@EnableFeignClients 3.定义一个接口</p><p>@FeignClient(name=“xxx”)指定调用哪个服务</p><h2 id="_54-14-ribbon和feign的区别" tabindex="-1">54. 14， Ribbon和Feign的区别？ <a class="header-anchor" href="#_54-14-ribbon和feign的区别" aria-label="Permalink to &quot;54. 14， Ribbon和Feign的区别？&quot;">​</a></h2><p>1.Ribbon都是调用其他服务的，但方式不同。 2.启动类注解不同，Ribbon是@RibbonClient feign</p><p>的是@EnableFeignClients 3.服务指定的位置不同，Ribbon是在@RibbonClient注解上声明，Feign 则是在定义抽象方法的接口中使用@FeignClient声明。 4.调用方式不同，Ribbon需要自己构建http 请求，模拟http请求</p><h2 id="附-一句话速记-可以跳过-★☆☆" tabindex="-1">附：一句话速记（可以跳过 ★☆☆） <a class="header-anchor" href="#附-一句话速记-可以跳过-★☆☆" aria-label="Permalink to &quot;附：一句话速记（可以跳过 ★☆☆）&quot;">​</a></h2><ul><li><strong>2PC</strong> 的 <strong>XA</strong>：数据库层协议，<strong>同步阻塞</strong>重，现在基本只做了解。</li><li><strong>Forking 容错</strong>：并行调多个实例取最快返回，浪费资源，只在<strong>极低延迟</strong>要求时用。</li></ul>',467)]))}const S=r(k,[["render",P]]);export{y as __pageData,S as default};
